const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const title = String($json.title ?? '').trim();
const narrationScript = String($json.narration_script ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Script Complete Item did not atomically claim a valid content_id. Ensure a script_complete row exists and run from the start.');
}
if (!title) {
  throw new Error('Fetch Next Script Complete Item did not produce a title.');
}
if (!narrationScript) {
  throw new Error('Fetch Next Script Complete Item did not produce a narration_script.');
}
return [{
  json: {
    content_id: contentId,
    title,
    category: String($json.category ?? 'general').trim() || 'general',
    target_duration_seconds: Number($json.target_duration_seconds ?? 45),
    narration_script: narrationScript,
    short_script: String($json.short_script ?? ''),
    onscreen_text_json: $json.onscreen_text_json ?? [],
    brand_tone: 'cinematic, concise, credible',
    visual_style_rules: 'realistic, moody, high contrast, cinematic composition, vertical-frame friendly',
    subtitle_style_rules: 'short lines, high contrast, mobile readable, centered safely above app UI',
    status_after_success: 'storyboard_complete'
  }
}];

if (!$json.content_id || !$json.title || !$json.narration_script) {
  throw new Error('Prepare Storyboard Prompt Payload did not provide the required fields to Build Storyboard Request.');
}
const systemPrompt = [
  'You are the storyboard planner for a faceless English-language Instagram Reel channel focused on cinematic mystery, history, and unexplained-storytelling content.',
  '',
  'Your job is to turn a completed narration script into a scene-by-scene storyboard package that can be used for:',
  '',
  '- scene asset generation',
  '- subtitle planning',
  '- cover prompt generation',
  '- render manifest construction',
  '',
  'Hard rules:',
  '',
  '- preserve the factual confidence and tone of the script',
  '- do not introduce new factual claims that are not already implied by the narration',
  '- keep the scenes visually concrete and production-friendly',
  '- prefer scenes that can be rendered or sourced with clear prompts',
  '- keep scene count tight enough for a short-form Reel',
  '- keep subtitle lines readable on mobile',
  '- avoid overloading a single scene with too much narration',
  '',
  'Storyboard rules:',
  '',
  '- target 4 to 8 scenes',
  '- total scene durations should fit within ' + $json.target_duration_seconds + ' seconds',
  '- every scene must have a clear visual prompt',
  '- every scene must have narration-aligned subtitle text',
  '- transitions should stay simple and reusable',
  '',
  'Brand direction:',
  '',
  '- tone: ' + $json.brand_tone,
  '- visual style rules: ' + $json.visual_style_rules,
  '- subtitle style rules: ' + $json.subtitle_style_rules,
  '',
  'Return only valid JSON matching the provided response schema.'
].join('\n');
const userPrompt = [
  'Create a storyboard package for this Reel.',
  '',
  'Title:',
  $json.title,
  '',
  'Category:',
  $json.category,
  '',
  'Target duration:',
  String($json.target_duration_seconds),
  '',
  'Narration script:',
  $json.narration_script,
  '',
  'Requirements:',
  '',
  '- break the script into scenes that follow the narration pacing',
  '- distribute duration sensibly across scenes',
  '- write cinematic visual prompts for each scene',
  '- create concise subtitle lines that match the spoken content',
  '- generate one cover prompt aligned with the same visual language',
  '- include render seed data that later steps can extend',
  '',
  'Return fields:',
  '',
  '- storyboard_json',
  '- cover_prompt',
  '- subtitle_lines_json',
  '- style_notes',
  '- visual_style_summary',
  '- render_manifest_seed_json',
  '',
  'Return only JSON.'
].join('\n');
return [{
  json: {
    content_id: $json.content_id,
    title: $json.title,
    status_after_success: $json.status_after_success,
    openai_request: {
      model: String($env.OPENAI_STORYBOARD_MODEL || $env.OPENAI_TEXT_MODEL || 'gpt-4o-mini').trim(),
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      response_schema: {
        type: 'object',
        additionalProperties: false,
        required: [
          'storyboard_json',
          'cover_prompt',
          'subtitle_lines_json',
          'style_notes',
          'visual_style_summary',
          'render_manifest_seed_json'
        ],
        properties: {
          storyboard_json: {
            type: 'array',
            minItems: 4,
            maxItems: 8,
            items: {
              type: 'object',
              additionalProperties: false,
              required: [
                'scene_number',
                'duration_seconds',
                'narration_text',
                'visual_prompt',
                'asset_type',
                'transition',
                'mood'
              ],
              properties: {
                scene_number: { type: 'integer', minimum: 1 },
                duration_seconds: { type: 'number', exclusiveMinimum: 0 },
                narration_text: { type: 'string', minLength: 1 },
                visual_prompt: { type: 'string', minLength: 1 },
                asset_type: { type: 'string', enum: ['image', 'video'] },
                transition: { type: 'string', minLength: 1 },
                mood: { type: 'string', minLength: 1 }
              }
            }
          },
          cover_prompt: { type: 'string', minLength: 1 },
          subtitle_lines_json: {
            type: 'array',
            minItems: 1,
            items: {
              type: 'object',
              additionalProperties: false,
              required: ['scene_number', 'text'],
              properties: {
                scene_number: { type: 'integer', minimum: 1 },
                text: { type: 'string', minLength: 1 }
              }
            }
          },
          style_notes: { type: 'string', minLength: 1 },
          visual_style_summary: { type: 'string', minLength: 1 },
          render_manifest_seed_json: {
            type: 'object',
            additionalProperties: false,
            required: ['output', 'timeline', 'subtitles'],
            properties: {
              output: {
                type: 'object',
                additionalProperties: false,
                required: ['width', 'height', 'fps', 'format'],
                properties: {
                  width: { type: 'integer', minimum: 1 },
                  height: { type: 'integer', minimum: 1 },
                  fps: { type: 'integer', minimum: 1 },
                  format: { type: 'string', minLength: 1 }
                }
              },
              timeline: {
                type: 'array',
                items: {
                  type: 'object',
                  additionalProperties: false,
                  required: ['scene_number', 'duration_seconds', 'asset_type', 'transition'],
                  properties: {
                    scene_number: { type: 'integer', minimum: 1 },
                    duration_seconds: { type: 'number', exclusiveMinimum: 0 },
                    asset_type: { type: 'string', enum: ['image', 'video'] },
                    transition: { type: 'string', minLength: 1 }
                  }
                }
              },
              subtitles: {
                type: 'object',
                additionalProperties: false,
                required: ['enabled', 'style'],
                properties: {
                  enabled: { type: 'boolean' },
                  style: { type: 'string', minLength: 1 }
                }
              }
            }
          }
        }
      }
    }
  }
}];

if (!$json.content_id || !$json.openai_request) {
  throw new Error('Build Storyboard Request did not provide the expected OpenAI request payload.');
}
const apiKey = String($env.OPENAI_API_KEY || $env.LLL_API_KEY || '').trim();
if (!apiKey) {
  throw new Error('Set OPENAI_API_KEY in the repo-root .env before running wf_storyboard_and_prompts. For backward compatibility, LLL_API_KEY is also accepted.');
}
const request = $json.openai_request;
if (!request.model) {
  throw new Error('No OpenAI model was configured for the storyboard workflow.');
}
const response = await helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/chat/completions',
  json: true,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
  headers: {
    Authorization: 'Bearer ' + apiKey,
    'Content-Type': 'application/json'
  },
  body: {
    model: request.model,
    messages: request.messages,
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'storyboard_package',
        schema: request.response_schema,
        strict: true
      }
    }
  }
});
const statusCode = Number(response.statusCode ?? 0);
const body = response.body ?? {};
if (!(statusCode >= 200 && statusCode < 300) || body.error) {
  throw new Error('OpenAI storyboard call failed (' + (statusCode || 'no status') + '): ' + (body?.error?.message ?? 'unknown error'));
}
const content = body?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error('OpenAI storyboard call returned no message content.');
}
let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('OpenAI storyboard response was not valid JSON: ' + error.message);
}
return [{
  json: {
    content_id: $json.content_id,
    status_after_success: $json.status_after_success,
    generation_model: String(body.model ?? request.model),
    storyboard_response: parsed,
    provider_metadata: {
      response_id: body.id ?? null,
      usage: body.usage ?? null,
      finish_reason: body?.choices?.[0]?.finish_reason ?? null
    }
  }
}];

const response = $json.storyboard_response ?? {};
if (!$json.content_id) {
  throw new Error('Call OpenAI Storyboard Model did not provide content_id.');
}
if (!Array.isArray(response.storyboard_json) || response.storyboard_json.length < 4 || response.storyboard_json.length > 8) {
  throw new Error('Call OpenAI Storyboard Model must produce 4 to 8 storyboard scenes.');
}
if (!Array.isArray(response.subtitle_lines_json) || response.subtitle_lines_json.length === 0) {
  throw new Error('Call OpenAI Storyboard Model did not produce subtitle_lines_json.');
}
const storyboardJson = response.storyboard_json.map((scene, index) => ({
  scene_number: Number(scene?.scene_number ?? index + 1),
  duration_seconds: Number(scene?.duration_seconds ?? 0),
  narration_text: String(scene?.narration_text ?? '').trim(),
  visual_prompt: String(scene?.visual_prompt ?? '').trim(),
  asset_type: String(scene?.asset_type ?? '').trim(),
  transition: String(scene?.transition ?? '').trim(),
  mood: String(scene?.mood ?? '').trim()
}));
if (storyboardJson.some((scene) => !Number.isInteger(scene.scene_number) || scene.scene_number < 1 || !Number.isFinite(scene.duration_seconds) || scene.duration_seconds <= 0 || !scene.narration_text || !scene.visual_prompt || !['image', 'video'].includes(scene.asset_type) || !scene.transition || !scene.mood)) {
  throw new Error('storyboard_json contains invalid scene data.');
}
const subtitleLines = response.subtitle_lines_json.map((line, index) => ({
  scene_number: Number(line?.scene_number ?? index + 1),
  text: String(line?.text ?? '').trim()
}));
if (subtitleLines.some((line) => !Number.isInteger(line.scene_number) || line.scene_number < 1 || !line.text)) {
  throw new Error('subtitle_lines_json contains invalid subtitle data.');
}
const renderManifestSeedJson = response.render_manifest_seed_json ?? {};
if (!renderManifestSeedJson.output || !Array.isArray(renderManifestSeedJson.timeline) || !renderManifestSeedJson.subtitles) {
  throw new Error('render_manifest_seed_json is missing output, timeline, or subtitles.');
}
return [{
  json: {
    content_id: $json.content_id,
    status_after_success: $json.status_after_success,
    storyboard_json: storyboardJson,
    cover_prompt: String(response.cover_prompt ?? '').trim(),
    subtitle_lines_json: subtitleLines,
    style_notes: String(response.style_notes ?? '').trim() + '\n\nVisual style summary: ' + String(response.visual_style_summary ?? '').trim() + '\nModel: ' + String($json.generation_model ?? '').trim(),
    render_manifest_seed_json: renderManifestSeedJson,
    raw_storyboard_json: {
      provider: 'openai',
      generation_model: String($json.generation_model ?? '').trim(),
      provider_metadata: $json.provider_metadata ?? {},
      parsed_response: response
    }
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error(`Prepare Storyboard SQL Values received an invalid content_id: ${contentId || '<empty>'}.`);
}
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    storyboard_json_sql: JSON.stringify($json.storyboard_json ?? []).replaceAll("'", "''"),
    cover_prompt_sql: String($json.cover_prompt ?? '').replaceAll("'", "''"),
    subtitle_lines_json_sql: JSON.stringify($json.subtitle_lines_json ?? []).replaceAll("'", "''"),
    style_notes_sql: String($json.style_notes ?? '').replaceAll("'", "''"),
    render_manifest_seed_json_sql: JSON.stringify($json.render_manifest_seed_json ?? {}).replaceAll("'", "''")
  }
}];
